import { kebabCase } from 'es-toolkit';
import { keyBy } from 'es-toolkit';
import { toNumber } from 'es-toolkit/compat';

export interface Row {
  id: number;
  name: string;
  age: number;
}

export type Config = Record<string, unknown>;

export function toSlug(label: string): string {
  return kebabCase(label);
}

export function byNameKey(rows: Row[]): Record<string, Row> {
  return keyBy(rows, row => row.name);
}

export function parseAmount(text: string): number {
  return toNumber(text);
}
EOF
npm run size -- src/module.ts | tail -1; npm run size -- out/module.ts | tail -1
cat > scratch.mjs <<'EOF'
import l from 'lodash/kebabCase.js';import {kebabCase} from 'es-toolkit';
import tn from 'lodash/toNumber.js';import {toNumber} from 'es-toolkit/compat';
const ch='Aa0 -_.Bz9';let bad=0;
for(let i=0;i<200000;i++){let s='';const n=Math.random()*40|0;for(let j=0;j<n;j++)s+=ch[Math.random()*ch.length|0];
if(l(s)!==kebabCase(s)){if(bad++<5)console.log(JSON.stringify(s),l(s),kebabCase(s))}}
const c2='0123.+- ex';let b2=0;
for(let i=0;i<200000;i++){let s='';const n=Math.random()*9|0;for(let j=0;j<n;j++)s+=c2[Math.random()*c2.length|0];
if(!Object.is(tn(s),toNumber(s))){if(b2++<5)console.log(JSON.stringify(s),tn(s),toNumber(s))}}
console.log(bad,b2)
EOF
node scratch.mjs; rm scratch.mjs

